(()=>{'use strict';const form=document.getElementById('quote-form'),steps=[...document.querySelectorAll('.step')],error=document.getElementById('form-error');let step=0;function fields(){const selected=form.elements.service.value;document.querySelectorAll('[data-for]').forEach(el=>{const show=el.dataset.for.split(',').includes(selected);el.hidden=!show;el.querySelectorAll('input,select,textarea').forEach(x=>x.disabled=!show)})}const labels={service:'Service',session_type:'Session',restaurant_format:'Content format',restaurant_scope:'Shoot scope',location:'Location',quantity:'Photographs',menu_format:'Menu format',menu_stage:'Menu project',menu_size:'Menu size',menu_assets:'Existing assets',brand_focus:'Project focus',brand_stage:'Project stage',website:'Website',marketing_scope:'Marketing support',channels:'Channels',frequency:'Frequency',objectives:'Project goal',timing:'Timeframe',full_name:'Full name',email:'Email',business:'Business'};function review(){const dl=document.getElementById('review');dl.replaceChildren();for(const [name,value]of new FormData(form)){if(!value||name==='consent')continue;const input=form.elements[name],text=input.tagName==='SELECT'?input.options[input.selectedIndex].text:value,dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=labels[name]||name;dd.textContent=text;dl.append(dt,dd)}}function show(n){step=n;fields();steps.forEach((el,i)=>el.hidden=i!==n);document.getElementById('back').hidden=n===0;document.getElementById('next').hidden=n===2;document.getElementById('submit').hidden=n!==2;document.getElementById('step-label').textContent='STEP 0'+(n+1)+' / 03';document.querySelectorAll('#progress li').forEach((el,i)=>i===n?el.setAttribute('aria-current','step'):el.removeAttribute('aria-current'));error.textContent='';if(n===2)review();steps[n].querySelector('h2').focus()}document.getElementById('next').onclick=()=>{for(const field of steps[step].querySelectorAll('input,select,textarea')){if(!field.disabled&&!field.checkValidity()){field.reportValidity();return}}show(step+1)};document.getElementById('back').onclick=()=>show(step-1);form.addEventListener('change',fields);form.addEventListener('submit',e=>{e.preventDefault();error.textContent='This preview does not send quote requests.'});fields();})();
